<?php
require_once __DIR__.'/production.php';
function bizProductionRows(array $quantities): array {$rows=[];foreach($quantities as $pid=>$qty){$qty=positiveInt($qty,0,100000);if(!$qty)continue;$p=query('SELECT * FROM biz_products WHERE id=? AND active=1',[positiveInt($pid,1,PHP_INT_MAX)])->fetch();if(!$p)throw new InvalidArgumentException('생산 상품을 확인하세요.');$rows[]=[...$p,'qty'=>$qty];}return $rows;}
function bizProductionMaterials(array $rows): array {
 $totals=[];$missing=[];foreach($rows as $p){$r=query('SELECT r.*,l.weight_g FROM biz_recipe_links l JOIN biz_recipes r ON r.id=l.recipe_id AND r.active=1 WHERE l.product_id=?',[$p['id']])->fetch();if(!$r){$missing[]=bizKo($p);continue;}$scale=$r['base_unit']==='개'?(int)$p['qty']:((int)$r['weight_g']*(int)$p['qty']);if(!$scale){$missing[]=bizKo($p).' (제품 무게 확인 필요)';continue;}$lines=json_decode($r['ingredients'],true);$units=array_column($lines,'unit','material');foreach(productionMaterials($r,$scale) as $name=>$amount){$key=$name.'|'.($units[$name]??'g');if(!isset($totals[$key]))$totals[$key]=['name'=>$name,'unit'=>$units[$name]??'g','amount'=>0];$totals[$key]['amount']+=$amount;}}
 return ['totals'=>array_values($totals),'missing'=>$missing];
}
function bizProductionSelection(array $selected): array {
 $quantities=[];$sources=[];foreach(array_unique($selected) as $key){$o=bizBatch((string)$key);$lines=query('SELECT p.id,p.ko,d.planned FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.batch_key=? AND d.cancelled=0 AND d.sent=0',[$key])->fetchAll();if(!$lines)throw new InvalidArgumentException('이미 납품한 주문이 포함되어 있습니다. 새로고침하세요.');$c=query('SELECT name,address FROM biz_clients WHERE id=?',[$o['client_id']])->fetch();$sources[]=['batch'=>$key,'name'=>$c['name'],'address'=>$c['address'],'day'=>$o['day'],'items'=>$lines];foreach($lines as $line)$quantities[$line['id']]=($quantities[$line['id']]??0)+(int)$line['planned'];}return ['quantities'=>$quantities,'orders'=>$sources];
}
function bizProductionAction(string $action): string {
 if($action==='biz_production_save'){$key=textfield($_POST,'request_key',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new InvalidArgumentException('화면을 새로 여세요.');if($id=query('SELECT id FROM biz_production_plans WHERE request_key=?',[$key])->fetchColumn())return 'biz-production&id='.$id;$ids=$_POST['batches']??[];if(!is_array($ids)||!$ids)throw new InvalidArgumentException('생산할 주문을 선택하세요.');$s=bizProductionSelection($ids);$rows=bizProductionRows($s['quantities']);$s['rows']=$rows;$s['materials']=bizProductionMaterials($rows);query('INSERT INTO biz_production_plans (request_key,plan_date,title,snapshot,created_by) VALUES (?,?,?,?,?)',[$key,validDate(textfield($_POST,'plan_date',10,true)),textfield($_POST,'title',100,true),json_encode($s,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$_SESSION['user_id']]);return 'biz-production&id='.db()->lastInsertId();}
 if($action==='biz_recipe_links'){foreach($_POST['recipe']??[] as $pid=>$rid){$pid=positiveInt($pid,1,PHP_INT_MAX);$rid=positiveInt($rid,0,PHP_INT_MAX);if(!query('SELECT id FROM biz_products WHERE id=?',[$pid])->fetchColumn()||($rid&&!query('SELECT id FROM biz_recipes WHERE id=? AND active=1',[$rid])->fetchColumn()))throw new InvalidArgumentException('상품과 배합 기준을 확인하세요.');$weight=positiveInt($_POST['weight'][$pid]??0,0,1000000);query('INSERT INTO biz_recipe_links VALUES (?,?,?) ON DUPLICATE KEY UPDATE recipe_id=VALUES(recipe_id),weight_g=VALUES(weight_g)',[$pid,$rid?:null,$weight?:null]);}return 'biz-production-settings';}
 $id=positiveInt($_POST['id']??0,0,PHP_INT_MAX);
 if($action==='biz_recipe_delete'){query('UPDATE biz_recipes SET active=0 WHERE id=?',[$id]);return 'biz-production-settings';}
 if($action!=='biz_recipe_save')throw new InvalidArgumentException('생산 업무를 확인하세요.');$name=textfield($_POST,'name',100,true);$base=positiveInt($_POST['base_g']??0,1,1000000);$baseUnit=optionalChoice($_POST,'base_unit',['g','개'])?:'g';$lines=[];$seen=[];
 foreach(['material','basis','mode','amount','unit'] as $field)if(!is_array($_POST[$field]??null)||count($_POST[$field])>100)throw new InvalidArgumentException('재료 입력을 확인하세요.');
 foreach($_POST['material'] as $i=>$m){$m=textfield(['m'=>$m],'m',40);if(!$m)continue;if(isset($seen[$m])||in_array($m,['product','제품무게'],true))throw new InvalidArgumentException('재료 이름이 중복되거나 예약된 이름입니다.');$seen[$m]=true;$mode=$_POST['mode'][$i]??'';$unit=$_POST['unit'][$i]??'g';if(!in_array($mode,['percent','grams'],true)||!in_array($unit,['g','개','컵','줄'],true))throw new InvalidArgumentException('재료 단위를 확인하세요.');$basis=textfield(['v'=>$_POST['basis'][$i]??'product'],'v',40,true);$basis=$basis==='제품무게'?'product':$basis;if($mode==='percent'&&($unit!=='g'||$baseUnit!=='g'))throw new InvalidArgumentException('%는 제품과 재료 모두 무게(g) 기준일 때 사용하세요.');$lines[]=['material'=>$m,'basis'=>$basis,'mode'=>$mode,'unit'=>$unit,'amount'=>productionNumber($_POST['amount'][$i]??'',1000000)];}
 if(!$lines)throw new InvalidArgumentException('주재료를 하나 이상 입력하세요.');$units=array_column($lines,'unit','material');foreach($lines as $line)if($line['mode']==='percent'&&$line['basis']!=='product'&&($units[$line['basis']]??null)!=='g')throw new InvalidArgumentException('비율 기준 재료도 g 단위여야 합니다.');$json=json_encode($lines,JSON_UNESCAPED_UNICODE);productionMaterials(['ingredients'=>$json,'base_g'=>$base],$base);
 if($id){if(!query('SELECT id FROM biz_recipes WHERE id=? AND active=1',[$id])->fetchColumn())throw new InvalidArgumentException('삭제된 배합 기준입니다.');query('UPDATE biz_recipes SET name=?,base_g=?,base_unit=?,ingredients=? WHERE id=?',[$name,$base,$baseUnit,$json,$id]);}else query('INSERT INTO biz_recipes (name,base_g,base_unit,ingredients) VALUES (?,?,?,?)',[$name,$base,$baseUnit,$json]);return 'biz-production-settings';
}
